\title{Fuss--Catalan Numbers, Dyck Paths, and the Recursive Decomposition
Underlying Greedy $m$-Tamari Intervals}
\author{Aristotle}
\date{July 12, 2026}

\begin{document}

\begin{abstract}
We develop, from first principles, a single connected chain of results centered on
the \emph{Fuss--Catalan numbers}
$\FC(m,n) = \tfrac{1}{mn+1}\binom{(m+1)n}{n}$,
the enumerative backbone of every ``via Dyck paths'' statement in the greedy
$m$-Tamari / $(m+1)$-constellation program. We prove the universal base cases
$\FC(m,0)=\FC(m,1)=1$ for all arities $m$, and we treat the base layer $m=1$ --- the
ordinary Catalan numbers --- in full. For $m=1$ we establish the exact integrality
identity $(n+1)C_n = \binom{2n}{n}$, strict positivity, the Catalan-convolution
recursive decomposition $C_{n+1}=\sum_{i=0}^{n} C_i C_{n-i}$, monotonicity
$C_n \le C_{n+1}$, and a uniform lower bound $C_n \ge 1$. We then close the
combinatorial loop: $C_n$ simultaneously enumerates Dyck paths of semilength $n$,
binary trees with $n$ internal nodes, and plane (planar) trees with $n+1$ nodes. The
last identity is obtained by constructing the classical Knuth left-child /
right-sibling bijection between ordered plane forests and binary trees from scratch
and verifying that it preserves the node count. As a corollary, plane trees with
$n+1$ nodes are in explicit bijection with Dyck paths of semilength $n$. We situate
these results as the fully rigorous base layer of the greedy $m$-Tamari interval
program and outline the general-$m$ generalizations required to complete it.
\end{abstract}

\maketitle

\section{Introduction}

The Catalan numbers $C_n = \frac{1}{n+1}\binom{2n}{n} = 1,1,2,5,14,42,\dots$ are
among the most ubiquitous sequences in enumerative combinatorics. Their higher-arity
generalizations, the \emph{Fuss--Catalan numbers}
$\FC(m,n) = \frac{1}{mn+1}\binom{(m+1)n}{n}$, count $(m+1)$-ary plane trees with $n$
internal nodes and, equivalently, the $m$-Dyck paths of length $(m+1)n$.

Our motivation comes from a conjecture of Bousquet-M\'elou and Chapoton, generalized
to arbitrary arity $m$: the number of maximal \emph{greedy $m$-Tamari intervals} in a
planar $(m+1)$-constellation equals the number of maximal planar trees with $m$
internally labeled vertices, the correspondence being realized \emph{through Dyck
path structures}. Every ``via Dyck paths'' step rests on the arithmetic and bijective
theory of the Fuss--Catalan numbers. This paper establishes that foundation
rigorously at the base layer $m=1$, where the objects are Dyck paths, binary trees,
and plane trees, and records the universal facts holding for all $m$.

The paper is organized as a \emph{chain}: each result is used by the next.

\section{Definitions}

\begin{definition}[Fuss--Catalan number]
For nonnegative integers $m,n$ define
$\FC(m,n) = \big\lfloor \binom{(m+1)n}{n}/(mn+1) \big\rfloor$,
the division taken in the natural numbers. For the cases of interest the division is
exact. For $m=1$ this reduces to the Catalan number $C_n$.
\end{definition}

\begin{definition}[Central binomial coefficient]
$\cb(n) = \binom{2n}{n}$.
\end{definition}

\begin{definition}[Dyck path]
A \emph{Dyck path} of \emph{semilength} $n$ is a lattice path from $(0,0)$ to
$(2n,0)$ using up-steps $(1,1)$ and down-steps $(1,-1)$ that never passes below the
horizontal axis; equivalently, a balanced string of $n$ openings and $n$ closings in
which every prefix has at least as many openings as closings. Write $\Dyck_n$ for
this set.
\end{definition}

\begin{definition}[Binary tree]
A \emph{binary tree} is either the empty tree $\bot$ or an internal node carrying an
ordered pair of binary trees. Write $\Bin_n$ for the set of binary trees with $n$
internal nodes.
\end{definition}

\begin{definition}[Plane tree and plane forest]
A \emph{plane tree} is a root together with a finite \emph{ordered list} of plane
trees, its children. Its node count is
$\nu(\node(t_1,\dots,t_k)) = 1 + \sum_{i=1}^{k}\nu(t_i)$. A \emph{plane forest} is a
finite ordered list $f=(t_1,\dots,t_k)$ with $\nu(f)=\sum_i \nu(t_i)$. Write
$\Plane_n$ for the set of plane trees with $n$ nodes.
\end{definition}

\section{The arithmetic chain}

\begin{theorem}[Empty object; all $m$]
For every $m$, $\FC(m,0)=1$.
\end{theorem}
\begin{proof}
With $n=0$ the formula reads $\binom{0}{0}/(0+1)=1$.
\end{proof}

\begin{theorem}[Root-only object; all $m$]
For every $m$, $\FC(m,1)=1$.
\end{theorem}
\begin{proof}
With $n=1$ the numerator is $\binom{m+1}{1}=m+1$ and the denominator is $m+1$, so the
quotient is $1$.
\end{proof}

\begin{theorem}[Base layer]
For every $n$, $\FC(1,n)=C_n$.
\end{theorem}
\begin{proof}
With $m=1$ the numerator is $\binom{2n}{n}=\cb(n)$ and the denominator is $n+1$,
which is precisely $C_n=\cb(n)/(n+1)$.
\end{proof}

\begin{theorem}[Exactness / integrality]
For every $n$, $(n+1)C_n = \binom{2n}{n}$.
\end{theorem}
\begin{proof}
The divisibility $(n+1)\mid\binom{2n}{n}$ makes $C_n=\binom{2n}{n}/(n+1)$ exact;
multiplying by $n+1$ recovers $\binom{2n}{n}$. The divisibility follows from the
identity $\binom{2n}{n}-\binom{2n}{n+1}=C_n$, which exhibits $C_n$ as an integer.
\end{proof}

\begin{theorem}[Positivity]
For every $n$, $C_n>0$.
\end{theorem}
\begin{proof}
If $C_n=0$ then the previous theorem gives $\binom{2n}{n}=0$, contradicting strict
positivity of the central binomial coefficient.
\end{proof}

\begin{theorem}[Recursive decomposition --- Catalan convolution]
For every $n$, $C_{n+1}=\sum_{i=0}^{n} C_i\,C_{n-i}$.
\end{theorem}
\begin{proof}
A nonempty Dyck path $w$ of semilength $n+1$ has a well-defined first return to the
axis. Writing $w = u\,v\,D\,w'$ with $u$ the initial up-step, $D$ the down-step of
the first return, $v$ the interior sub-path and $w'$ the remainder, the pair
$(v,w')$ ranges bijectively over $\bigsqcup_{i=0}^{n}\Dyck_i\times\Dyck_{n-i}$.
Counting yields the convolution. The same recursion arises by splitting a binary
tree at its root into left and right subtrees.
\end{proof}

\begin{theorem}[Monotonicity]
For every $n$, $C_n\le C_{n+1}$.
\end{theorem}
\begin{proof}
In $C_{n+1}=\sum_{i+j=n}C_iC_j$ the term $(i,j)=(n,0)$ contributes $C_n\cdot C_0=C_n$
and all other terms are nonnegative.
\end{proof}

\begin{theorem}[Lower bound]
For every $n$, $C_n\ge 1$.
\end{theorem}
\begin{proof}
Immediate from positivity, since $C_n$ is a positive integer.
\end{proof}

\section{Combinatorial identities and the Knuth bijection}

\begin{theorem}[Dyck paths --- the ``via Dyck paths'' identity]
For every $n$, $C_n = \#\,\Dyck_n$.
\end{theorem}
\begin{proof}
Dyck paths satisfy the same convolution recurrence (first-return decomposition) and
base value $\#\Dyck_0=1$ as the Catalan numbers.
\end{proof}

\begin{theorem}[Binary trees]
For every $n$, $C_n = \#\,\Bin_n$.
\end{theorem}
\begin{proof}
Binary trees with $n$ internal nodes satisfy the same convolution recurrence
(split at the root) and base case $\#\Bin_0=1$.
\end{proof}

\begin{definition}[Knuth transform]
Define $\Phi$ from plane forests to binary trees and $\Psi$ its putative inverse by
\[
\Phi([\,])=\bot,\qquad
\Phi(\node(t_1,\dots,t_k)::\mathit{rest})=\big(\Phi(t_1,\dots,t_k),\Phi(\mathit{rest})\big),
\]
\[
\Psi(\bot)=[\,],\qquad
\Psi((\ell,r))=\node(\Psi(\ell))::\Psi(r).
\]
\end{definition}

\begin{lemma}[Mutual inverses]
$\Psi\circ\Phi=\mathrm{id}$ on plane forests and $\Phi\circ\Psi=\mathrm{id}$ on
binary trees.
\end{lemma}
\begin{proof}
Structural induction, splitting a forest as empty versus
$\node(ts)::\mathit{rest}$ and a binary tree as $\bot$ versus $(\ell,r)$; the
recursive clauses reconstruct each other.
\end{proof}

\begin{lemma}[Size preservation]
For every plane forest $f$, $\Phi(f)$ has exactly $\nu(f)$ internal nodes.
\end{lemma}
\begin{proof}
Induction on $f$: the empty forest maps to $\bot$; for
$\node(ts)::\mathit{rest}$ the image is an internal node whose internal count is
$1+\nu(ts)+\nu(\mathit{rest})=\nu(\node(ts)::\mathit{rest})$ by induction.
\end{proof}

\begin{corollary}[Knuth bijection, graded]
For every $n$, $\Phi$ restricts to a bijection between plane forests with $n$ nodes
and binary trees with $n$ internal nodes; both families are counted by $C_n$.
\end{corollary}

\begin{theorem}[Plane trees]
For every $n$, $C_n = \#\,\Plane_{n+1}$.
\end{theorem}
\begin{proof}
A plane tree with $n+1$ nodes is its root plus the ordered forest of its children,
which has $n$ nodes; this correspondence is a bijection onto plane forests with $n$
nodes, counted by $C_n$ via the graded Knuth bijection.
\end{proof}

\begin{corollary}[Plane trees $\leftrightarrow$ Dyck paths]
For every $n$, $\#\,\Plane_{n+1} = \#\,\Dyck_n$.
\end{corollary}
\begin{proof}
Both equal $C_n$. Explicitly, strip a plane tree to its child-forest, apply $\Phi$,
and encode the resulting binary tree as a Dyck path by depth-first traversal.
\end{proof}

\section{Applications: the greedy $m$-Tamari program}

On $\Dyck_n$ there is a natural partial order whose Hasse diagram is the
\emph{Tamari lattice} $\mathcal{T}_n$; its intervals are pairs $(p,q)$ with $p\le q$
together with all paths between them. The Bousquet-M\'elou--Chapoton conjecture, in
its arity-$m$ generalization, predicts that maximal greedy $m$-Tamari intervals in a
planar $(m+1)$-constellation are equinumerous with maximal planar trees carrying $m$
internally labeled vertices, the correspondence realized via Dyck path structures,
the common count being Fuss--Catalan.

The results above are the rigorous base layer $m=1$: the arithmetic tower fixes the
exact values, positivity, self-similarity, and growth; the bijective tower realizes
those counts on Dyck paths, binary trees, and plane trees with explicit
dictionaries. Being bijective and grade-preserving, the correspondence can be
refined to track statistics (valleys, active sites), as the general conjecture
requires.

\section{Discussion and future work}

\begin{enumerate}
\item \textbf{General-$m$ integrality.} Prove $(mn+1)\mid\binom{(m+1)n}{n}$, giving
$(mn+1)\FC(m,n)=\binom{(m+1)n}{n}$ for all $m$; the standard route is the cycle lemma
(Dvoretzky--Motzkin).
\item \textbf{General-$m$ recursive decomposition.} Establish the $(m+1)$-fold
self-convolution
$\FC(m,n+1)=\sum_{k_1+\cdots+k_{m+1}=n}\FC(m,k_1)\cdots\FC(m,k_{m+1})$,
the shadow of $A=1+xA^{m+1}$ for $(m+1)$-ary trees.
\item \textbf{$(m+1)$-ary plane trees.} Generalize the plane-tree / Knuth bijection
to $(m+1)$-ary plane trees, proving their count is $\FC(m,n)$.
\item \textbf{The greedy $m$-Tamari interval bijection.} Build the
recursive-decomposition isomorphism between greedy $m$-Tamari intervals in a planar
$(m+1)$-constellation and maximal planar trees with $m$ internally labeled vertices,
refining the equinumerosity to the tracked statistics, and identify the common count
with the Fuss--Catalan numbers established here.
\end{enumerate}

\section{Conclusion}

We have assembled a single connected chain anchoring the greedy $m$-Tamari program at
its base. The Fuss--Catalan arithmetic --- with universal base cases
$\FC(m,0)=\FC(m,1)=1$ and the full integrality, positivity, convolution, and
monotonicity theory of the case $m=1$ --- is matched, bijectively and grade by
grade, with the enumeration of Dyck paths, binary trees, and plane trees. The Knuth
left-child / right-sibling bijection closes the loop between the ``planar tree'' and
``Dyck path'' sides, providing the solid ground for the general-$m$ theory.

\end{document}

