"""Fuss-Catalan arithmetic and the exact integrality identity."""
from math import comb
from typing import List


def fuss_catalan(m: int, n: int) -> int:
    """FC(m, n) = C((m+1)*n, n) / (m*n + 1), an exact integer division."""
    return comb((m + 1) * n, n) // (m * n + 1)


def catalan(n: int) -> int:
    """The n-th Catalan number = FC(1, n)."""
    return comb(2 * n, n) // (n + 1)


def verify_integrality(max_n: int = 15) -> List[int]:
    """Check the exactness identity (n+1)*C_n = C(2n, n) for n = 0..max_n."""
    cats: List[int] = []
    for n in range(max_n + 1):
        c = catalan(n)
        assert (n + 1) * c == comb(2 * n, n), "integrality violated"
        assert fuss_catalan(1, n) == c, "base layer FC(1,n)=C_n violated"
        assert comb((1 + 1) * n, n) % (n + 1) == 0, "division not exact"
        cats.append(c)
    return cats


if __name__ == "__main__":
    print("Catalan numbers C_0..C_15:", verify_integrality())
    print("FC(m,0), FC(m,1) for m=0..4:",
          [(fuss_catalan(m, 0), fuss_catalan(m, 1)) for m in range(5)])

"""The recursive decomposition: the Catalan convolution from first returns."""
from functools import lru_cache
from typing import List, Tuple


@lru_cache(maxsize=None)
def catalan(n: int) -> int:
    if n == 0:
        return 1
    return sum(catalan(i) * catalan(n - 1 - i) for i in range(n))


def dyck_paths(n: int) -> List[Tuple[int, ...]]:
    """Enumerate Dyck paths of semilength n as +/-1 step sequences."""
    out: List[Tuple[int, ...]] = []

    def rec(pref: Tuple[int, ...], ups: int, downs: int) -> None:
        if ups == n and downs == n:
            out.append(pref)
            return
        if ups < n:
            rec(pref + (1,), ups + 1, downs)
        if downs < ups:
            rec(pref + (-1,), ups, downs + 1)

    rec((), 0, 0)
    return out


def first_return_split(path: Tuple[int, ...]) -> Tuple[Tuple[int, ...], Tuple[int, ...]]:
    """Split a nonempty Dyck path at its first return: (interior, remainder)."""
    height = 0
    for i, step in enumerate(path):
        height += step
        if height == 0:
            return path[1:i], path[i + 1:]
    raise ValueError("not a Dyck path")


def verify_convolution(max_n: int = 8) -> None:
    for n in range(max_n):
        conv = sum(catalan(i) * catalan(n - i) for i in range(n + 1))
        assert conv == catalan(n + 1)
        # the first-return split realizes the convolution bijectively
        buckets = {}
        for p in dyck_paths(n + 1):
            interior, rest = first_return_split(p)
            i = len(interior) // 2
            buckets[i] = buckets.get(i, 0) + 1
        assert all(buckets[i] == catalan(i) * catalan(n - i)
                   for i in range(n + 1))
        print(f"C_{n+1} = {catalan(n+1)} = sum_i C_i*C_(n-i);  "
              f"first-return buckets match")


if __name__ == "__main__":
    verify_convolution()

"""The Knuth left-child/right-sibling bijection, enumerated and checked."""
from typing import List, Tuple, Optional

PlaneTree = Tuple            # tuple of child plane trees; () is a leaf
BinTree = Optional[Tuple]    # None or (left, right)


def plane_forests(n: int) -> List[Tuple[PlaneTree, ...]]:
    """All plane forests with n nodes total."""
    if n == 0:
        return [()]
    res: List[Tuple[PlaneTree, ...]] = []
    for k in range(1, n + 1):
        for cf in plane_forests(k - 1):
            head = cf
            for rest in plane_forests(n - k):
                res.append((head,) + rest)
    return res


def forest_to_bin(f: Tuple[PlaneTree, ...]) -> BinTree:
    if not f:
        return None
    head, *rest = f
    return (forest_to_bin(head), forest_to_bin(tuple(rest)))


def bin_to_forest(t: BinTree) -> Tuple[PlaneTree, ...]:
    if t is None:
        return ()
    left, right = t
    return (bin_to_forest(left),) + bin_to_forest(right)


def internal_nodes(t: BinTree) -> int:
    if t is None:
        return 0
    l, r = t
    return 1 + internal_nodes(l) + internal_nodes(r)


def verify_knuth(max_n: int = 7) -> None:
    for n in range(max_n + 1):
        forests = plane_forests(n)
        images = set()
        for f in forests:
            b = forest_to_bin(f)
            assert bin_to_forest(b) == f, "not invertible"
            assert internal_nodes(b) == n, "not size preserving"
            images.add(repr(b))
        assert len(images) == len(forests), "not injective"
        print(f"n={n}: {len(forests)} plane forests <-> "
              f"{len(images)} binary trees (Catalan number)")


if __name__ == "__main__":
    verify_knuth()

