function FUSS_CATALAN(m, n):
    numerator   <- binomial((m + 1) * n, n)
    denominator <- m * n + 1
    return integer_division(numerator, denominator)

function CATALAN(n):
    if n = 0: return 1
    total <- 0
    for i in 0 .. n-1:
        total <- total + CATALAN(i) * CATALAN(n-1-i)
    return total

function FOREST_TO_BIN(forest):
    if forest is empty: return NIL
    head <- first tree of forest       # head is its list of children
    rest <- remaining forest
    return NODE(FOREST_TO_BIN(head), FOREST_TO_BIN(rest))

function BIN_TO_FOREST(tree):
    if tree = NIL: return empty forest
    (left, right) <- tree
    return  [ NODE(BIN_TO_FOREST(left)) ]  ++  BIN_TO_FOREST(right)

